class RuntimeError(val position: Position, val reason: String) : Exception(reason)
object Builtins {
    fun format(values: List<Value>, position: Position): String {
        val format = values[0].text;
        val output = StringBuilder();
        var i = 0;
        var argument = 1
        fun error(message: String): RuntimeError = RuntimeError(position, message)
        while (i < format.length) {
            if (format[i] != '%') {
                output.append(format[i++]);
                continue
            };
            i++
            if (format.getOrNull(i) == '%') {
                output.append('%');
                i++;
                continue
            }
            var left = false;
            var zero = false
            while (format.getOrNull(i) in listOf('-', '0')) {
                left = left || format[i] == '-';
                zero = zero || format[i] == '0';
                i++
            }
            val start = i;
            while (i < format.length && Lexer.digit(format[i])) i++;
            val width = format.substring(start, i).toIntOrNull() ?: 0
            var precision: Int? = null
            if (format.getOrNull(i) == '.') {
                i++;
                val begin = i;
                while (i < format.length && Lexer.digit(format[i])) i++;
                precision = format.substring(begin, i).toIntOrNull() ?: 0
            }
            if (i == format.length || format[i] !in "discxo") throw error("invalid format")
            val conversion = format[i++];
            if (argument == values.size) throw error("not enough arguments");
            val value = values[argument++];
            val numeric = conversion in "dixo"
            var body: String
            if (numeric) {
                val n = value.number;
                var digits = kotlin.math.abs(n).toString(if (conversion == 'x') 16 else if (conversion == 'o') 8 else 10);
                if (precision != null) digits = if (precision == 0 && n == 0) "" else digits.padStart(precision, '0');
                body = (if (n < 0) "-" else "") + digits
            }
            else if (conversion == 's') body = if (precision == null) value.text else value.text.take(precision)
            else if (value.numericKind) {
                val code = value.number;
                if (code != 10 && code !in 32..126) throw error("invalid character code");
                body = code.toChar().toString()
            }
            else body = value.text.take(1)
            if (body.length < width) {
                val padding = width - body.length;
                body = if (left) body + " ".repeat(padding) else if (numeric && zero && precision == null) {
                    if (body.startsWith("-")) "-" + "0".repeat(padding) + body.drop(1) else "0".repeat(padding) + body
                } else " ".repeat(padding) + body
            }
            output.append(body)
        }
        return output.toString()
    }
    fun scalar(name: String, values: List<Value>, position: Position): Value = when (name) {
        "substr" -> {
            val text = values[0].text;
            val original = values[1].number;
            val start = maxOf(1, original);
            val end = minOf(text.length + 1, if (values.size == 3) original + values[2].number else text.length + 1);
            Value.Text(if (end > start) text.substring(start - 1, end - 1) else "")
        }
        "index" -> {
            val text = values[0].text;
            val target = values[1].text;
            Value.Number(if (target.isEmpty()) 0 else text.indexOf(target) + 1)
        }
        "toupper" -> Value.Text(values[0].text.map {
            if (it in 'a'..'z') (it.code - 32).toChar() else it
        }.joinToString(""))
        "tolower" -> Value.Text(values[0].text.map {
            if (it in 'A'..'Z') (it.code + 32).toChar() else it
        }.joinToString(""))
        "int" -> Value.Number(values[0].number)
        else -> Value.Text(format(values, position))
    }
}

data class Position(val line: Int, val column: Int) : Comparable<Position> {
    override fun compareTo(other: Position): Int = compareValuesBy(this, other, Position::line, Position::column)
    override fun toString(): String = "$line:$column"
}
class SyntaxError(val position: Position) : Exception()
data class Token(val kind: String, val text: String, val value: String, val position: Position)
object Lexer {
    fun letter(c: Char): Boolean = c in 'A'..'Z' || c in 'a'..'z'
    fun digit(c: Char): Boolean = c in '0'..'9'
    fun lex(text: String): List<Token> {
        val positions = mutableListOf<Position>();
        var line = 1;
        var column = 1
        for (c in text) {
            positions.add(Position(line, column));
            if (c.code == 10) {
                line++;
                column = 1
            } else column++
        }
        positions.add(Position(line, column))
        val result = mutableListOf<Token>();
        var i = 0
        val keywords = setOf("BEGIN", "END", "function", "if", "else", "while", "for", "do", "break", "continue", "next", "exit", "return", "delete", "in", "getline", "print", "printf")
        val builtins = setOf("length", "substr", "index", "split", "sprintf", "toupper", "tolower", "close", "int")
        val symbols = setOf("+=", "-=", "*=", "/=", "%=", "^=", "==", "<=", ">=", "!=", "++", "--", "&&", "||", ">>")
        while (i < text.length) {
            if (text[i] == ' ') {
                i++;
                continue
            }
            if (text[i].code == 92 && text.getOrNull(i + 1)?.code == 10) {
                i += 2;
                continue
            }
            if (text[i] == '#') {
                while (i < text.length && text[i].code != 10) i++;
                continue
            }
            val start = i;
            var kind = "symbol";
            var value = ""
            if (text[i].code == 10) {
                i++;
                kind = "newline"
            }
            else if (digit(text[i])) {
                while (i < text.length && digit(text[i])) i++;
                kind = "number"
            }
            else if (letter(text[i]) || text[i] == '_') {
                while (i < text.length && (letter(text[i]) || digit(text[i]) || text[i] == '_')) i++
                val name = text.substring(start, i)
                kind = if (name in keywords) "keyword" else if (name in builtins) "builtin" else if (text.getOrNull(i) == '(') "function" else "name"
            } else if (text[i].code == 34) {
                i++;
                var closed = false;
                val decoded = StringBuilder()
                while (i < text.length) {
                    if (text[i].code == 10) throw SyntaxError(positions[start])
                    if (text[i].code == 34) {
                        i++;
                        closed = true;
                        break
                    }
                    if (text[i].code == 92) {
                        val slash = i++
                        if (i == text.length) throw SyntaxError(positions[start])
                        decoded.append(when (text[i].code) {
                            110 -> 10.toChar();
                            116 -> 9.toChar();
                            92, 34, 47 -> text[i];
                            else -> throw SyntaxError(positions[slash])
                        });
                        i++
                    } else decoded.append(text[i++])
                }
                if (!closed) throw SyntaxError(positions[start]);
                kind = "string";
                value = decoded.toString()
            } else if (i + 1 < text.length && text.substring(i, i + 2) in symbols) i += 2
            else if (text[i] in "+-*/%^!><?:=()[]{},;$") i++
            else throw SyntaxError(positions[i])
            result.add(Token(kind, text.substring(start, i), value, positions[start]))
        }
        result.add(Token("end", "", "", positions.last()));
        return result
    }
}

import java.io.File
data class NameKey(val scope: Int?, val name: String)
data class CallSite(val name: String, val arguments: List<Expr>, val scope: Int?, val position: Position)
class StaticError(val position: Position, val reason: String) : Exception(reason)
class Preparation(val program: Program) {
    val globals = mutableSetOf("FILENAME", "FNR", "FS", "NF", "NR", "OFS", "ORS", "SUBSEP");
    val arrays = mutableSetOf<NameKey>();
    val uses = mutableListOf<Pair<NameKey, Position>>();
    val calls = mutableListOf<CallSite>();
    val lines = mutableMapOf<Int, Int>();
    val functions = mutableMapOf<String, Int>()
    fun key(scope: Int?, name: String): NameKey = NameKey(if (scope != null && program.functions[scope].parameters.any {
        it.first == name
    }) scope else null, name)
    fun name(scope: Int?, name: String, position: Position, array: Boolean) {
        val key = key(scope, name);
        if (key.scope == null) globals.add(name);
        if (array) arrays.add(key);
        uses.add(key to position)
    }
    fun expression(expression: Expr, scope: Int?) {
        when (val kind = expression.kind) {
            is ExprKind.Name -> name(scope, kind.name, expression.position, false)
            is ExprKind.Index -> {
                name(scope, kind.name, expression.position, true);
                for (index in kind.indices) this.expression(index, scope)
            }
            is ExprKind.Field -> this.expression(kind.index, scope)
            is ExprKind.Parentheses -> this.expression(kind.body, scope)
            is ExprKind.Unary -> this.expression(kind.body, scope)
            is ExprKind.Increment -> this.expression(kind.target, scope)
            is ExprKind.Binary -> {
                this.expression(kind.left, scope);
                this.expression(kind.right, scope)
            }
            is ExprKind.Assignment -> {
                this.expression(kind.target, scope);
                this.expression(kind.right, scope)
            }
            is ExprKind.Conditional -> {
                this.expression(kind.condition, scope);
                this.expression(kind.yes, scope);
                this.expression(kind.no, scope)
            }
            is ExprKind.Member -> {
                for (index in kind.indices) this.expression(index, scope);
                name(scope, kind.name, kind.namePosition, true)
            }
            is ExprKind.Call -> {
                if (!kind.builtin) calls.add(CallSite(kind.name, kind.arguments, scope, expression.position));
                for (argument in kind.arguments) this.expression(argument, scope);
                if (kind.builtin && kind.name == "split") arrays.add(key(scope, (kind.arguments[1].kind as ExprKind.Name).name))
            }
            is ExprKind.Getline -> {
                kind.target?.let {
                    this.expression(it, scope)
                };
                kind.file?.let {
                    this.expression(it, scope)
                }
            }
            else -> Unit
        }
    }
    fun statement(statement: Stmt, scope: Int?) {
        if (statement.kind !is StmtKind.Block && statement.kind != StmtKind.Empty) lines[statement.position.line] = 0
        when (val kind = statement.kind) {
            is StmtKind.Block -> for (child in kind.statements) this.statement(child, scope)
            is StmtKind.Expression -> expression(kind.expression, scope)
            is StmtKind.Conditional -> {
                expression(kind.condition, scope);
                this.statement(kind.yes, scope);
                kind.no?.let {
                    this.statement(it, scope)
                }
            }
            is StmtKind.While -> {
                expression(kind.condition, scope);
                this.statement(kind.body, scope)
            }
            is StmtKind.Do -> {
                this.statement(kind.body, scope);
                expression(kind.condition, scope)
            }
            is StmtKind.For -> {
                for (value in listOfNotNull(kind.initial, kind.condition, kind.update)) expression(value, scope);
                this.statement(kind.body, scope)
            }
            is StmtKind.ForIn -> {
                name(scope, kind.variable, kind.variablePosition, false);
                name(scope, kind.array, kind.arrayPosition, true);
                this.statement(kind.body, scope)
            }
            is StmtKind.Output -> {
                for (argument in kind.arguments) expression(argument, scope);
                kind.redirect?.let {
                    expression(it.expression, scope)
                }
            }
            is StmtKind.Delete -> {
                name(scope, kind.name, kind.namePosition, true);
                for (index in kind.indices ?: emptyList()) expression(index, scope)
            }
            is StmtKind.Exit -> kind.expression?.let {
                expression(it, scope)
            }
            is StmtKind.Return -> kind.expression?.let {
                expression(it, scope)
            }
            else -> Unit
        }
    }
    fun analyze() {
        val errors = mutableListOf<Triple<Position, Int, String>>()
        for ((i, function) in program.functions.withIndex()) {
            if (function.name in functions) errors.add(Triple(function.position, 0, "function ${function.name} redefined")) else functions[function.name] = i
            val parameters = mutableSetOf<String>()
            for ((name, position) in function.parameters) {
                if (!parameters.add(name)) errors.add(Triple(position, 1, "duplicate parameter $name"));
                uses.add(NameKey(i, name) to position)
            }
            statement(function.body, i)
        }
        for (rule in program.rules) {
            rule.start?.let {
                expression(it, null)
            };
            rule.end?.let {
                expression(it, null)
            };
            rule.action?.let {
                statement(it, null)
            }
        }
        for ((key, position) in uses) {
            if (key.name in functions) errors.add(Triple(position, 2, "function ${key.name} used as variable"))
        }
        val links = mutableListOf<Pair<NameKey, NameKey>>()
        for (call in calls) {
            val callee = functions[call.name]
            if (callee == null) errors.add(Triple(call.position, 3, "undefined function ${call.name}"))
            else {
                val parameters = program.functions[callee].parameters;
                if (call.arguments.size > parameters.size) errors.add(Triple(call.position, 4, "too many arguments to ${call.name}"));
                for ((argument, parameter) in call.arguments.zip(parameters)) {
                    val name = argument.kind as? ExprKind.Name;
                    if (name != null) links.add(key(call.scope, name.name) to NameKey(callee, parameter.first))
                }
            }
        }
        val error = errors.minWithOrNull(compareBy<Triple<Position, Int, String>> {
            it.first
        }.thenBy {
            it.second
        })
        if (error != null) throw StaticError(error.first, error.third)
        while (true) {
            var changed = false;
            for ((a, b) in links) {
                if (a in arrays || b in arrays) {
                    if (arrays.add(a)) changed = true;
                    if (arrays.add(b)) changed = true
                }
            };
            if (!changed) break
        }
    }
}
class AwkArray {
    val elements = mutableMapOf<String, Value>()
}
sealed interface Cell
class ScalarCell(val value: Value) : Cell
class ArrayCell(val array: AwkArray) : Cell
sealed interface Location {
    data class Variable(val frame: Int?, val name: String) : Location
    data class Element(val array: AwkArray, val key: String) : Location
    data class Field(val index: Int) : Location
}
class Flow(val kind: String, val value: Value = Value.Uninitialized) : Exception()
data class MainInput(val file: Int, val lines: List<String>, var position: Int = 0)
class Runtime(val program: Program, val preparation: Preparation, val arguments: Arguments) {
    val fields = Fields();
    val streams = Streams();
    val globals = mutableMapOf<String, Cell>();
    val locals = mutableListOf<MutableMap<String, Cell>>();
    var operand = 0;
    var current: MainInput? = null;
    var phase = "BEGIN";
    var status = 0
    val rules = IntArray(program.rules.size);
    val ranges = BooleanArray(program.rules.size);
    val calls = IntArray(program.functions.size);
    val active = IntArray(program.functions.size);
    val depths = IntArray(program.functions.size)
    init {
        for (name in preparation.globals) globals[name] = if (NameKey(null, name) in preparation.arrays) ArrayCell(AwkArray()) else ScalarCell(Value.Uninitialized);
        for ((name, value) in listOf("FS" to Value.Text(" "), "OFS" to Value.Text(" "), "ORS" to Value.Text(10.toChar().toString()), "SUBSEP" to Value.Text(28.toChar().toString()), "NR" to Value.Number(0), "FNR" to Value.Number(0), "FILENAME" to Value.Text(""))) globals[name] = ScalarCell(value)
    }
    fun frame(name: String): Int? = if (locals.lastOrNull()?.containsKey(name) == true) locals.lastIndex else null
    fun cell(frame: Int?, name: String): Cell? = if (frame == null) globals[name] else locals[frame][name]
    fun array(name: String): AwkArray = (cell(frame(name), name) as ArrayCell).array
    fun value(frame: Int?, name: String): Value = if (frame == null && name == "NF") Value.Number(fields.values.size) else (cell(frame, name) as? ScalarCell)?.value ?: Value.Uninitialized
    fun global(name: String): Value = value(null, name)
    fun key(expressions: List<Expr>): String {
        val keys = expressions.map {
            expression(it).text
        };
        return keys.joinToString(global("SUBSEP").text)
    }
    fun location(expression: Expr): Location = when (val kind = expression.kind) {
        is ExprKind.Name -> Location.Variable(frame(kind.name), kind.name)
        is ExprKind.Index -> {
            val key = key(kind.indices);
            Location.Element(array(kind.name), key)
        }
        is ExprKind.Field -> {
            val number = this.expression(kind.index).number;
            if (number < 0) throw RuntimeError(expression.position, "negative field index");
            Location.Field(number)
        }
        else -> error("not an lvalue")
    }
    fun read(location: Location): Value = when (location) {
        is Location.Variable -> value(location.frame, location.name);
        is Location.Element -> location.array.elements.getOrPut(location.key) {
            Value.Uninitialized
        };
        is Location.Field -> fields.get(location.index)
    }
    fun store(location: Location, value: Value, position: Position): Value {
        when (location) {
            is Location.Variable -> if (location.frame == null && location.name == "NF") {
                val n = value.number;
                if (n < 0) throw RuntimeError(position, "negative NF");
                fields.nf(n, global("OFS").text)
            } else if (location.frame != null) locals[location.frame][location.name] = ScalarCell(value) else {
                preparation.globals.add(location.name);
                globals[location.name] = ScalarCell(value)
            }
            is Location.Element -> location.array.elements[location.key] = value
            is Location.Field -> fields.assign(location.index, value, global("FS").text, global("OFS").text)
        }
        return read(location)
    }
    fun arithmetic(op: String, a: Int, b: Int, position: Position): Value {
        if (op in listOf("/", "%") && b == 0) throw RuntimeError(position, "division by zero")
        if (op == "^" && b < 0) throw RuntimeError(position, "negative exponent")
        val value = when (op) {
            "+" -> a + b;
            "-" -> a - b;
            "*" -> a * b;
            "/" -> a / b;
            "%" -> a % b;
            else -> {
                var result = 1;
                var base = a;
                var exponent = b;
                while (exponent > 0) {
                    if (exponent % 2 == 1) result *= base;
                    exponent /= 2;
                    if (exponent > 0) base *= base
                };
                result
            }
        }
        return Value.Number(value)
    }
    fun expression(expression: Expr): Value {
        val position = expression.position
        return when (val kind = expression.kind) {
            is ExprKind.Number -> Value.Number(kind.value)
            is ExprKind.Text -> Value.Text(kind.value)
            is ExprKind.Name, is ExprKind.Index, is ExprKind.Field -> read(location(expression))
            is ExprKind.Parentheses -> this.expression(kind.body)
            is ExprKind.Unary -> {
                val value = this.expression(kind.body);
                Value.Number(if (kind.op == "-") -value.number else if (kind.op == "+") value.number else if (value.truth) 0 else 1)
            }
            is ExprKind.Binary -> {
                val a = this.expression(kind.left)
                if (kind.op == "||" && a.truth) Value.Number(1) else if (kind.op == "&&" && !a.truth) Value.Number(0)
                else {
                    val b = this.expression(kind.right);
                    if (kind.op in listOf("||", "&&")) Value.Number(if (b.truth) 1 else 0) else if (kind.op == "concat") Value.Text(a.text + b.text) else if (kind.op in listOf("<", "<=", "==", "!=", ">=", ">")) {
                        val order = a.compare(b);
                        val result = when (kind.op) {
                            "<" -> order < 0;
                            "<=" -> order <= 0;
                            "==" -> order == 0;
                            "!=" -> order != 0;
                            ">=" -> order >= 0;
                            else -> order > 0
                        };
                        Value.Number(if (result) 1 else 0)
                    } else arithmetic(kind.op, a.number, b.number, position)
                }
            }
            is ExprKind.Assignment -> {
                val location = location(kind.target);
                val b = this.expression(kind.right);
                val value = if (kind.op == "=") b else arithmetic(kind.op.take(1), read(location).number, b.number, position);
                store(location, value, position)
            }
            is ExprKind.Increment -> {
                val location = location(kind.target);
                val value = read(location).number;
                store(location, Value.Number(value + kind.delta), position);
                Value.Number(if (kind.prefix) value + kind.delta else value)
            }
            is ExprKind.Conditional -> this.expression(if (this.expression(kind.condition).truth) kind.yes else kind.no)
            is ExprKind.Member -> {
                val key = key(kind.indices);
                Value.Number(if (key in array(kind.name).elements) 1 else 0)
            }
            is ExprKind.Call -> if (kind.builtin) builtin(kind.name, kind.arguments, position) else call(kind.name, kind.arguments)
            is ExprKind.Getline -> {
                val pair = if (kind.file != null) streams.getline(this.expression(kind.file).text) else if (phase == "END") 0 to null else {
                    val line = nextRecord();
                    (if (line == null) 0 else 1) to line
                }
                val line = pair.second
                if (line != null) {
                    if (kind.target != null) store(location(kind.target), Value.input(line), position) else fields.set(line, global("FS").text)
                }
                Value.Number(pair.first)
            }
        }
    }
    fun builtin(name: String, arguments: List<Expr>, position: Position): Value {
        if (name == "length") {
            if (arguments.isEmpty()) return Value.Number(fields.record.text.length);
            val single = arguments[0].kind as? ExprKind.Name;
            if (single != null) {
                val cell = cell(frame(single.name), single.name);
                if (cell is ArrayCell) return Value.Number(cell.array.elements.size)
            };
            return Value.Number(expression(arguments[0]).text.length)
        }
        if (name == "split") {
            val text = expression(arguments[0]).text;
            val separator = if (arguments.size == 3) expression(arguments[2]).text else global("FS").text;
            val array = array((arguments[1].kind as ExprKind.Name).name);
            val pieces = splitText(text, separator);
            array.elements.clear();
            for ((i, piece) in pieces.withIndex()) array.elements[(i + 1).toString()] = Value.input(piece);
            return Value.Number(pieces.size)
        }
        val values = arguments.map {
            expression(it)
        };
        return if (name == "close") Value.Number(streams.close(values[0].text)) else Builtins.scalar(name, values, position)
    }
    fun call(name: String, arguments: List<Expr>): Value {
        val index = preparation.functions.getValue(name);
        val function = program.functions[index];
        val local = mutableMapOf<String, Cell>()
        for ((i, parameter) in function.parameters.withIndex()) {
            local[parameter.first] = if (NameKey(index, parameter.first) in preparation.arrays) ArrayCell(if (i < arguments.size) array((arguments[i].kind as ExprKind.Name).name) else AwkArray()) else ScalarCell(if (i < arguments.size) expression(arguments[i]) else Value.Uninitialized)
        }
        calls[index]++;
        active[index]++;
        depths[index] = maxOf(depths[index], active[index]);
        locals.add(local)
        try {
            statement(function.body);
            return Value.Uninitialized
        } catch (flow: Flow) {
            if (flow.kind == "return") return flow.value;
            throw flow
        } finally {
            locals.removeAt(locals.lastIndex);
            active[index]--
        }
    }
    fun output(printf: Boolean, arguments: List<Expr>, redirect: Redirect?, position: Position) {
        val values = arguments.map {
            expression(it)
        }
        val text = if (printf) Builtins.format(values, position) else (if (values.isEmpty()) listOf(fields.record) else values).joinToString(global("OFS").text) {
            it.text
        } + global("ORS").text
        if (redirect != null) {
            val name = expression(redirect.expression).text;
            if (!validFile(name) || name in listOf("stdout.txt", "stats.txt")) throw RuntimeError(redirect.position, "invalid output file name");
            streams.output(name, redirect.append, text)
        } else streams.output(null, false, text)
    }
    fun loopBody(body: Stmt): Boolean = try {
        statement(body);
        true
    } catch (flow: Flow) {
        when (flow.kind) {
            "continue" -> true;
            "break" -> false;
            else -> throw flow
        }
    }
    fun statement(statement: Stmt) {
        val position = statement.position
        if (statement.kind !is StmtKind.Block && statement.kind != StmtKind.Empty) preparation.lines[position.line] = preparation.lines.getValue(position.line) + 1
        when (val kind = statement.kind) {
            is StmtKind.Block -> for (child in kind.statements) this.statement(child)
            StmtKind.Empty -> Unit
            is StmtKind.Expression -> {
                expression(kind.expression)
            }
            is StmtKind.Conditional -> if (expression(kind.condition).truth) this.statement(kind.yes) else kind.no?.let {
                this.statement(it)
            }
            is StmtKind.While -> {
                while (expression(kind.condition).truth) {
                    if (!loopBody(kind.body)) break
                }
            }
            is StmtKind.Do -> {
                do {
                    if (!loopBody(kind.body)) break
                } while (expression(kind.condition).truth)
            }
            is StmtKind.For -> {
                kind.initial?.let {
                    expression(it)
                };
                while (kind.condition == null || expression(kind.condition).truth) {
                    if (!loopBody(kind.body)) break;
                    kind.update?.let {
                        expression(it)
                    }
                }
            }
            is StmtKind.ForIn -> {
                val keys = array(kind.array).elements.keys.sortedWith(keyOrder);
                for (key in keys) {
                    store(Location.Variable(frame(kind.variable), kind.variable), Value.input(key), kind.variablePosition);
                    if (!loopBody(kind.body)) break
                }
            }
            is StmtKind.Output -> output(kind.printf, kind.arguments, kind.redirect, position)
            is StmtKind.Delete -> {
                val key = kind.indices?.let {
                    key(it)
                };
                val array = array(kind.name);
                if (key == null) array.elements.clear() else array.elements.remove(key)
            }
            StmtKind.Next -> {
                if (phase == "BEGIN" || phase == "END") throw RuntimeError(position, "next used in BEGIN or END");
                throw Flow("next")
            }
            StmtKind.Break -> throw Flow("break")
            StmtKind.Continue -> throw Flow("continue")
            is StmtKind.Exit -> {
                kind.expression?.let {
                    status = expression(it).number
                };
                throw Flow("exit")
            }
            is StmtKind.Return -> throw Flow("return", kind.expression?.let {
                expression(it)
            } ?: Value.Uninitialized)
        }
    }
    fun nextRecord(): String? {
        while (true) {
            val input = current
            if (input != null && input.position < input.lines.size) {
                val line = input.lines[input.position++];
                arguments.files[input.file].records++;
                val nr = global("NR").number + 1;
                val fnr = global("FNR").number + 1;
                globals["NR"] = ScalarCell(Value.Number(nr));
                globals["FNR"] = ScalarCell(Value.Number(fnr));
                return line
            }
            if (operand == arguments.operands.size) return null
            when (val next = arguments.operands[operand++]) {
                is Operand.Assignment -> {
                    preparation.globals.add(next.name);
                    globals[next.name] = ScalarCell(Value.input(next.value))
                }
                is Operand.Input -> {
                    globals["FILENAME"] = ScalarCell(Value.Text(next.name));
                    globals["FNR"] = ScalarCell(Value.Number(0));
                    current = MainInput(next.index, readFile(next.name)!!)
                }
            }
        }
    }
    fun testRule(rule: Rule, index: Int): Boolean {
        if (rule.kind == "all") return true
        if (rule.kind == "range") {
            if (!ranges[index] && expression(rule.start!!).truth) ranges[index] = true;
            val matched = ranges[index];
            if (matched && expression(rule.end!!).truth) ranges[index] = false;
            return matched
        }
        return expression(rule.start!!).truth
    }
    fun execute() {
        for ((name, value) in arguments.options) {
            preparation.globals.add(name);
            globals[name] = ScalarCell(Value.input(value))
        }
        var exiting = false
        for ((i, rule) in program.rules.withIndex()) {
            if (rule.kind == "BEGIN") {
                rules[i]++;
                try {
                    statement(rule.action!!)
                } catch (flow: Flow) {
                    if (flow.kind != "exit") throw flow;
                    exiting = true;
                    break
                }
            }
        }
        phase = "rules"
        if (!exiting && program.rules.any {
            it.kind != "BEGIN"
        }) {
            records@ while (true) {
                val record = nextRecord() ?: break;
                fields.set(record, global("FS").text)
                for ((i, rule) in program.rules.withIndex()) {
                    if (rule.kind in listOf("BEGIN", "END")) continue
                    try {
                        if (testRule(rule, i)) {
                            rules[i]++;
                            if (rule.action != null) statement(rule.action) else streams.output(null, false, fields.record.text + global("ORS").text)
                        }
                    }
                    catch (flow: Flow) {
                        if (flow.kind == "next") continue@records;
                        if (flow.kind == "exit") break@records;
                        throw flow
                    }
                }
            }
        }
        phase = "END"
        for ((i, rule) in program.rules.withIndex()) {
            if (rule.kind == "END") {
                rules[i]++;
                try {
                    statement(rule.action!!)
                } catch (flow: Flow) {
                    if (flow.kind != "exit") throw flow;
                    break
                }
            }
        }
    }
    fun report(status: String) {
        streams.save()
        val lines = mutableListOf(status, "[inputs]")
        for (file in arguments.files) lines.add("${file.name} records=${file.records}")
        lines.add("[getline]")
        for (input in streams.inputs) lines.add(if (input.opened) "${input.name} reads=${input.reads}" else "${input.name} missing")
        lines.add("[rules]")
        for ((i, rule) in program.rules.withIndex()) lines.add("${rule.position} ${rule.kind} count=${rules[i]}")
        lines.add("[functions]")
        for ((i, function) in program.functions.withIndex()) lines.add("${function.name} calls=${calls[i]} depth=${depths[i]}")
        lines.addAll(listOf("[outputs]", "stdout.txt writes=${streams.writes} bytes=${streams.stdout.length}"))
        for (output in streams.outputs) lines.add("${output.name} writes=${output.writes} bytes=${output.text.length}")
        lines.add("[lines]")
        for (line in preparation.lines.keys.sorted()) lines.add("$line count=${preparation.lines.getValue(line)}")
        lines.add("[globals]")
        for (name in preparation.globals.sorted()) {
            val cell = globals[name];
            val display = if (cell is ArrayCell) "array (${cell.array.elements.size})" else global(name).display;
            lines.add("$name = $display")
        }
        saveStats(lines)
    }
}
fun saveStats(lines: List<String>) {
    File("output").mkdirs();
    File("output/stats.txt").writeText(lines.joinToString("\n") + "\n")
}
fun failure(status: String) {
    File("output").mkdirs();
    File("output/stdout.txt").writeText("");
    saveStats(listOf(status))
}
fun main() {
    val program = try {
        Parser(Lexer.lex(File("input/program.awk").readText())).program()
    } catch (error: SyntaxError) {
        failure("status: syntax error at ${error.position}");
        return
    }
    val preparation = Preparation(program)
    try {
        preparation.analyze()
    } catch (error: StaticError) {
        failure("status: error at ${error.position}: ${error.reason}");
        return
    }
    val runtime = Runtime(program, preparation, arguments(File("input/args.txt").readText()))
    val status = try {
        runtime.execute();
        "status: exit ${runtime.status}"
    } catch (error: RuntimeError) {
        "status: runtime error at ${error.position}: ${error.reason}"
    }
    runtime.report(status)
}

data class Expr(val position: Position, val kind: ExprKind) {
    val lvalue: Boolean get() = kind is ExprKind.Name || kind is ExprKind.Index || kind is ExprKind.Field
}
sealed interface ExprKind {
    data class Number(val value: Int) : ExprKind
    data class Text(val value: String) : ExprKind
    data class Name(val name: String) : ExprKind
    data class Index(val name: String, val indices: List<Expr>) : ExprKind
    data class Field(val index: Expr) : ExprKind
    data class Parentheses(val body: Expr) : ExprKind
    data class Unary(val op: String, val body: Expr) : ExprKind
    data class Binary(val op: String, val left: Expr, val right: Expr) : ExprKind
    data class Assignment(val op: String, val target: Expr, val right: Expr) : ExprKind
    data class Increment(val delta: Int, val prefix: Boolean, val target: Expr) : ExprKind
    data class Conditional(val condition: Expr, val yes: Expr, val no: Expr) : ExprKind
    data class Member(val indices: List<Expr>, val name: String, val namePosition: Position) : ExprKind
    data class Call(val name: String, val builtin: Boolean, val arguments: List<Expr>) : ExprKind
    data class Getline(val target: Expr?, val file: Expr?) : ExprKind
}
data class Stmt(val position: Position, val kind: StmtKind)
data class Redirect(val append: Boolean, val expression: Expr, val position: Position)
sealed interface StmtKind {
    data class Block(val statements: List<Stmt>) : StmtKind
    data object Empty : StmtKind
    data class Expression(val expression: Expr) : StmtKind
    data class Conditional(val condition: Expr, val yes: Stmt, val no: Stmt?) : StmtKind
    data class While(val condition: Expr, val body: Stmt) : StmtKind
    data class Do(val body: Stmt, val condition: Expr) : StmtKind
    data class For(val initial: Expr?, val condition: Expr?, val update: Expr?, val body: Stmt) : StmtKind
    data class ForIn(val variable: String, val variablePosition: Position, val array: String, val arrayPosition: Position, val body: Stmt) : StmtKind
    data class Output(val printf: Boolean, val arguments: List<Expr>, val redirect: Redirect?) : StmtKind
    data class Delete(val name: String, val namePosition: Position, val indices: List<Expr>?) : StmtKind
    data object Next : StmtKind
    data object Break : StmtKind
    data object Continue : StmtKind
    data class Exit(val expression: Expr?) : StmtKind
    data class Return(val expression: Expr?) : StmtKind
}
data class Function(val name: String, val position: Position, val parameters: List<Pair<String, Position>>, val body: Stmt)
data class Rule(val kind: String, val position: Position, val start: Expr?, val end: Expr?, val action: Stmt?)
data class Program(val rules: List<Rule>, val functions: List<Function>)
class Parser(val tokens: List<Token>) {
    var index = 0;
    var function = false;
    var special = false;
    var loops = 0
    val peek: Token get() = tokens[index]
    val text: String get() = peek.text
    fun take(): Token {
        val token = peek;
        if (token.kind != "end") index++;
        return token
    }
    fun expect(text: String): Token {
        if (this.text != text || peek.kind == "end") throw SyntaxError(peek.position);
        return take()
    }
    fun name(): Token {
        if (peek.kind != "name") throw SyntaxError(peek.position);
        return take()
    }
    fun newlines() {
        while (peek.kind == "newline") take()
    }
    fun terminator() {
        if (text == ";" || peek.kind == "newline") take() else if (text != "}") throw SyntaxError(peek.position)
    }
    fun expressions(suppress: Boolean): List<Expr> {
        val result = mutableListOf(expression(suppress));
        while (text == ",") {
            take();
            newlines();
            result.add(expression(suppress))
        };
        return result
    }
    fun expression(suppress: Boolean = false): Expr {
        val left = conditional(suppress);
        if (left.lvalue && text in listOf("=", "+=", "-=", "*=", "/=", "%=", "^=")) {
            val token = take();
            return Expr(token.position, ExprKind.Assignment(token.text, left, expression(suppress)))
        };
        return left
    }
    fun conditional(suppress: Boolean): Expr {
        val condition = binary(1, suppress);
        if (text == "?") {
            val token = take();
            val yes = conditional(suppress);
            expect(":");
            return Expr(token.position, ExprKind.Conditional(condition, yes, conditional(suppress)))
        };
        return condition
    }
    fun binary(minimum: Int, suppress: Boolean): Expr {
        var left = unary(suppress)
        while (true) {
            val explicit = when (text) {
                "||" -> 1;
                "&&" -> 2;
                "in" -> 3;
                "<", "<=", "==", "!=", ">=" -> 4;
                ">" -> if (suppress) 0 else 4;
                "+", "-" -> 6;
                "*", "/", "%" -> 7;
                else -> 0
            }
            val concat = explicit == 0 && (peek.kind in listOf("number", "string", "name", "function", "builtin") || text in listOf("$", "(", "++", "--"));
            val priority = if (concat) 5 else explicit
            if (priority == 0 || priority < minimum) return left
            if (explicit == 3) {
                val token = take();
                val name = this.name();
                left = Expr(token.position, ExprKind.Member(listOf(left), name.text, name.position));
                continue
            }
            val position = peek.position;
            val op = if (concat) "concat" else take().text
            if (op == "||" || op == "&&") newlines()
            left = Expr(position, ExprKind.Binary(op, left, binary(priority + 1, suppress)))
        }
    }
    fun unary(suppress: Boolean): Expr {
        if (text in listOf("!", "-", "+")) {
            val token = take();
            return Expr(token.position, ExprKind.Unary(token.text, unary(suppress)))
        };
        val left = postfix(suppress);
        if (text == "^") {
            val token = take();
            return Expr(token.position, ExprKind.Binary(token.text, left, unary(suppress)))
        };
        return left
    }
    fun prefix(suppress: Boolean): Expr {
        val token = take();
        return Expr(token.position, ExprKind.Increment(if (token.text == "++") 1 else -1, true, lvalue(suppress)))
    }
    fun postfix(suppress: Boolean): Expr {
        if (text == "++" || text == "--") return prefix(suppress);
        val body = atom(suppress);
        if (body.lvalue && (text == "++" || text == "--")) {
            val token = take();
            return Expr(token.position, ExprKind.Increment(if (token.text == "++") 1 else -1, false, body))
        };
        return body
    }
    fun lvalue(suppress: Boolean): Expr {
        if (peek.kind != "name" && text != "$") throw SyntaxError(peek.position);
        return atom(suppress)
    }
    fun atom(suppress: Boolean): Expr {
        val token = peek
        val kind: ExprKind = when (token.kind) {
            "number" -> {
                take();
                ExprKind.Number(token.text.toInt())
            }
            "string" -> {
                take();
                ExprKind.Text(token.value)
            }
            "name" -> {
                take();
                if (text == "[") {
                    take();
                    val indices = expressions(false);
                    expect("]");
                    ExprKind.Index(token.text, indices)
                } else ExprKind.Name(token.text)
            }
            "function", "builtin" -> {
                take();
                val builtin = token.kind == "builtin";
                var arguments: List<Expr> = emptyList()
                if (text == "(") {
                    take();
                    if (text != ")") arguments = expressions(false);
                    expect(")")
                } else if (!builtin || token.text != "length") throw SyntaxError(peek.position)
                if (builtin) {
                    val n = arguments.size;
                    val valid = when (token.text) {
                        "length" -> n <= 1;
                        "substr" -> n == 2 || n == 3;
                        "index" -> n == 2;
                        "split" -> (n == 2 || n == 3) && arguments[1].kind is ExprKind.Name;
                        "sprintf" -> n >= 1;
                        else -> n == 1
                    };
                    if (!valid) throw SyntaxError(token.position)
                }
                ExprKind.Call(token.text, builtin, arguments)
            }
            else -> when (token.text) {
                "$" -> {
                    take();
                    ExprKind.Field(if (text == "++" || text == "--") prefix(suppress) else atom(suppress))
                }
                "(" -> {
                    take();
                    val values = expressions(false);
                    expect(")");
                    if (values.size == 1) ExprKind.Parentheses(values[0]) else {
                        expect("in");
                        val name = this.name();
                        ExprKind.Member(values, name.text, name.position)
                    }
                }
                "getline" -> {
                    take();
                    val target = if (peek.kind == "name" || text == "$") lvalue(suppress) else null;
                    val file = if (text == "<") {
                        take();
                        atom(suppress)
                    } else null;
                    ExprKind.Getline(target, file)
                }
                else -> throw SyntaxError(token.position)
            }
        }
        return Expr(token.position, kind)
    }
    fun block(): Stmt {
        val position = expect("{").position;
        val statements = mutableListOf<Stmt>();
        while (text != "}") {
            if (peek.kind == "newline" || text == ";") take() else statements.add(statement())
        };
        expect("}");
        return Stmt(position, StmtKind.Block(statements))
    }
    fun loopBody(): Stmt {
        newlines();
        loops++;
        val body = statement();
        loops--;
        return body
    }
    fun statement(): Stmt {
        val token = peek;
        val position = token.position
        val kind: StmtKind = when (text) {
            "{" -> return block()
            ";" -> {
                take();
                return Stmt(position, StmtKind.Empty)
            }
            "if" -> {
                take();
                expect("(");
                val condition = expression();
                expect(")");
                newlines();
                val yes = statement();
                newlines();
                val no = if (text == "else") {
                    take();
                    newlines();
                    statement()
                } else null;
                return Stmt(position, StmtKind.Conditional(condition, yes, no))
            }
            "while" -> {
                take();
                expect("(");
                val condition = expression();
                expect(")");
                return Stmt(position, StmtKind.While(condition, loopBody()))
            }
            "do" -> {
                take();
                val body = loopBody();
                newlines();
                expect("while");
                expect("(");
                val condition = expression();
                expect(")");
                StmtKind.Do(body, condition)
            }
            "for" -> {
                take();
                expect("(")
                if (index + 3 < tokens.size && tokens[index].kind == "name" && tokens[index + 1].text == "in" && tokens[index + 2].kind == "name" && tokens[index + 3].text == ")") {
                    val variable = name();
                    take();
                    val array = name();
                    take();
                    return Stmt(position, StmtKind.ForIn(variable.text, variable.position, array.text, array.position, loopBody()))
                }
                val initial = if (text == ";") null else expression();
                expect(";");
                newlines();
                val condition = if (text == ";") null else expression();
                expect(";");
                newlines();
                val update = if (text == ")") null else expression();
                expect(")");
                return Stmt(position, StmtKind.For(initial, condition, update, loopBody()))
            }
            "print", "printf" -> {
                take();
                val printf = token.text == "printf";
                val empty = text in listOf(";", 10.toChar().toString(), "}", ">", ">>");
                var parenthesized = false
                if (text == "(") {
                    var depth = 0;
                    for (i in index until tokens.size) {
                        if (tokens[i].text == "(") depth++ else if (tokens[i].text == ")") {
                            depth--;
                            if (depth == 0) {
                                parenthesized = i + 1 < tokens.size && (tokens[i + 1].text in listOf(";", 10.toChar().toString(), "}", ">", ">>") || tokens[i + 1].kind == "end");
                                break
                            }
                        }
                    }
                }
                if (empty && printf) throw SyntaxError(peek.position)
                val arguments = if (empty) emptyList() else if (parenthesized) {
                    take();
                    val values = expressions(false);
                    expect(")");
                    values
                } else expressions(true)
                val redirect = if (text == ">" || text == ">>") {
                    val op = take();
                    Redirect(op.text == ">>", binary(5, false), op.position)
                } else null
                StmtKind.Output(printf, arguments, redirect)
            }
            "delete" -> {
                take();
                val name = this.name();
                val indices = if (text == "[") {
                    take();
                    val values = expressions(false);
                    expect("]");
                    values
                } else null;
                StmtKind.Delete(name.text, name.position, indices)
            }
            "next" -> {
                take();
                if (special && !function) throw SyntaxError(position);
                StmtKind.Next
            }
            "break", "continue" -> {
                take();
                if (loops == 0) throw SyntaxError(position);
                if (token.text == "break") StmtKind.Break else StmtKind.Continue
            }
            "exit", "return" -> {
                take();
                if (token.text == "return" && !function) throw SyntaxError(position);
                val value = if (text in listOf(";", 10.toChar().toString(), "}")) null else expression();
                if (token.text == "exit") StmtKind.Exit(value) else StmtKind.Return(value)
            }
            else -> StmtKind.Expression(expression())
        }
        terminator();
        return Stmt(position, kind)
    }
    fun program(): Program {
        val rules = mutableListOf<Rule>();
        val functions = mutableListOf<Function>()
        while (peek.kind != "end") {
            if (text == ";" || peek.kind == "newline") {
                take();
                continue
            };
            val position = peek.position
            if (text == "function") {
                take();
                if (peek.kind != "name" && peek.kind != "function") throw SyntaxError(peek.position);
                val name = take();
                expect("(");
                val parameters = mutableListOf<Pair<String, Position>>()
                if (text != ")") {
                    while (true) {
                        val parameter = this.name();
                        parameters.add(parameter.text to parameter.position);
                        if (text != ",") break;
                        take();
                        newlines()
                    }
                }
                expect(")");
                newlines();
                function = true;
                val body = block();
                function = false;
                functions.add(Function(name.text, name.position, parameters, body))
            } else if (text == "BEGIN" || text == "END") {
                val kind = take().text;
                special = true;
                val action = block();
                special = false;
                rules.add(Rule(kind, position, null, null, action))
            }
            else if (text == "{") rules.add(Rule("all", position, null, null, block()))
            else {
                val start = expression();
                val end = if (text == ",") {
                    take();
                    newlines();
                    expression()
                } else null;
                val action = if (text == "{") block() else {
                    if (text != ";" && peek.kind != "newline" && peek.kind != "end") throw SyntaxError(peek.position);
                    null
                };
                rules.add(Rule(if (end == null) "pattern" else "range", position, start, end, action))
            }
        }
        return Program(rules, functions)
    }
}

import java.io.File
sealed interface Operand {
    data class Assignment(val name: String, val value: String) : Operand
    data class Input(val name: String, val index: Int) : Operand
}
data class FileCount(val name: String, var records: Int = 0)
data class Arguments(val options: MutableList<Pair<String, String>> = mutableListOf(), val operands: MutableList<Operand> = mutableListOf(), val files: MutableList<FileCount> = mutableListOf())
fun validFile(text: String): Boolean = text.isNotEmpty() && !text.startsWith(".") && text.all {
    Lexer.letter(it) || Lexer.digit(it) || it in "._-"
}
fun readFile(name: String): List<String>? = if (validFile(name) && File("input/$name").isFile) File("input/$name").readLines() else null
fun arguments(text: String): Arguments {
    val result = Arguments()
    fun assignment(text: String): Pair<String, String>? {
        val i = text.indexOf('=');
        return if (i < 0) null else text.substring(0, i) to text.substring(i + 1)
    }
    fun variable(text: String): Boolean = text.isNotEmpty() && (Lexer.letter(text[0]) || text[0] == '_') && text.all {
        Lexer.letter(it) || Lexer.digit(it) || it == '_'
    }
    for (line in text.lineSequence().filter {
        it.isNotEmpty()
    }) {
        if (line.startsWith("-F ")) result.options.add("FS" to line.drop(3))
        else if (line.startsWith("-v ")) result.options.add(assignment(line.drop(3))!!)
        else {
            val pair = assignment(line);
            if (pair != null && variable(pair.first)) result.operands.add(Operand.Assignment(pair.first, pair.second)) else {
                result.operands.add(Operand.Input(line, result.files.size));
                result.files.add(FileCount(line))
            }
        }
    }
    return result
}
class OutputStream(val name: String) {
    var text = "";
    var writes = 0;
    var open = false
}
class InputStream(val name: String) {
    var lines: List<String>? = null;
    var position = 0;
    var reads = 0;
    var opened = false;
    var open = false
}
class Streams {
    var stdout = "";
    var writes = 0;
    val outputs = mutableListOf<OutputStream>();
    val inputs = mutableListOf<InputStream>()
    fun output(name: String?, append: Boolean, text: String) {
        if (name == null) {
            stdout += text;
            writes++;
            return
        }
        val output = outputs.firstOrNull {
            it.name == name
        } ?: OutputStream(name).also {
            outputs.add(it)
        }
        if (!output.open) {
            output.open = true;
            if (!append) output.text = ""
        };
        output.text += text;
        output.writes++
    }
    fun getline(name: String): Pair<Int, String?> {
        val input = inputs.firstOrNull {
            it.name == name
        } ?: InputStream(name).also {
            inputs.add(it)
        }
        if (!input.open) {
            input.lines = readFile(name);
            input.position = 0;
            if (input.lines != null) {
                input.open = true;
                input.opened = true
            }
        }
        val lines = input.lines ?: return -1 to null
        if (input.position == lines.size) return 0 to null
        val line = lines[input.position++];
        input.reads++;
        return 1 to line
    }
    fun close(name: String): Int {
        var closed = false;
        outputs.firstOrNull {
            it.name == name
        }?.let {
            closed = closed || it.open;
            it.open = false
        };
        inputs.firstOrNull {
            it.name == name
        }?.let {
            closed = closed || it.open;
            it.open = false
        };
        return if (closed) 0 else -1
    }
    fun save() {
        File("output").mkdirs();
        File("output/stdout.txt").writeText(stdout);
        for (output in outputs) File("output/" + output.name).writeText(output.text)
    }
}

sealed interface Value {
    data class Number(val value: Int) : Value
    data class Text(val value: String) : Value
    data class Numeric(val value: String, override val number: Int) : Value
    data object Uninitialized : Value
    val number: Int get() = when (this) {
        is Number -> value;
        is Numeric -> number;
        Uninitialized -> 0;
        is Text -> {
            var i = 0;
            while (i < value.length && whitespace(value[i])) i++;
            val negative = value.getOrNull(i) == '-';
            if (value.getOrNull(i) in listOf('+', '-')) i++;
            var n = 0;
            while (i < value.length && Lexer.digit(value[i])) {
                n = n * 10 + (value[i++] - '0')
            };
            if (negative) -n else n
        }
    }
    val text: String get() = when (this) {
        is Number -> value.toString();
        is Text -> value;
        is Numeric -> value;
        Uninitialized -> ""
    }
    val truth: Boolean get() = if (this is Text) value.isNotEmpty() else number != 0
    val numberLike: Boolean get() = this !is Text
    val numericKind: Boolean get() = this is Number || this is Numeric
    fun compare(other: Value): Int = if (numberLike && other.numberLike) number.compareTo(other.number) else text.compareTo(other.text)
    val display: String get() = when (this) {
        is Number -> value.toString();
        is Text -> quote(value);
        is Numeric -> quote(value) + " (strnum)";
        Uninitialized -> "(uninitialized)"
    }
    companion object {
        fun whitespace(c: Char): Boolean = c == ' ' || c.code == 9 || c.code == 10
        fun input(text: String): Value {
            val raw = text.trim(::whitespace);
            val digits = if (raw.firstOrNull() in listOf('+', '-')) raw.drop(1) else raw;
            return if (digits.isNotEmpty() && digits.all(Lexer::digit)) Numeric(text, Text(text).number) else Text(text)
        }
    }
}
fun quote(text: String): String = buildString {
    append(34.toChar());
    for (c in text) {
        when (c.code) {
            34, 92 -> {
                append(92.toChar());
                append(c)
            };
            10 -> {
                append(92.toChar());
                append('n')
            };
            9 -> {
                append(92.toChar());
                append('t')
            };
            in 32..126 -> append(c);
            else -> {
                append(92.toChar());
                append(c.code.toString(8).padStart(3, '0'))
            }
        }
    };
    append(34.toChar())
}
fun splitText(text: String, separator: String): List<String> {
    if (separator == " ") {
        val pieces = mutableListOf<String>();
        var i = 0;
        while (i < text.length) {
            while (i < text.length && Value.whitespace(text[i])) i++;
            val start = i;
            while (i < text.length && !Value.whitespace(text[i])) i++;
            if (i > start) pieces.add(text.substring(start, i))
        };
        return pieces
    }
    if (separator.isEmpty()) return text.map(Char::toString)
    return if (text.isEmpty()) emptyList() else text.split(separator)
}
fun integerKey(text: String): Int? {
    if (text == "0") return 0;
    val digits = if (text.startsWith("-")) text.drop(1) else text;
    val first = digits.firstOrNull() ?: return null;
    if (first !in '1'..'9' || !digits.all(Lexer::digit)) return null;
    return text.toInt()
}
val keyOrder = Comparator<String> {
    a, b -> val x = integerKey(a);
    val y = integerKey(b);
    if (x != null && y != null) x.compareTo(y) else if (x != null) -1 else if (y != null) 1 else a.compareTo(b)
}
class Fields {
    var record: Value = Value.Text("");
    val values = mutableListOf<Value>()
    fun set(text: String, separator: String) {
        record = Value.input(text);
        values.clear();
        values.addAll(splitText(text, separator).map {
            Value.input(it)
        })
    }
    fun get(index: Int): Value = if (index == 0) record else values.getOrNull(index - 1) ?: Value.Uninitialized
    fun rebuild(separator: String) {
        record = Value.input(values.joinToString(separator) {
            it.text
        })
    }
    fun assign(index: Int, value: Value, fs: String, ofs: String) {
        if (index == 0) set(value.text, fs) else {
            while (values.size < index) values.add(Value.Text(""));
            values[index - 1] = value;
            rebuild(ofs)
        }
    }
    fun nf(size: Int, ofs: String) {
        while (values.size > size) values.removeAt(values.lastIndex);
        while (values.size < size) values.add(Value.Text(""));
        rebuild(ofs)
    }
}
